def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water = int(my_status['no_water_days'])

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    dangerous_prev = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                b = float(prev['bid'])
                prev_bids.append(b)
                req = float(opp.get('water_requirement', WATER_REQ))
                obudget = float(opp.get('budget', 0.0))
                ono = int(opp.get('no_water_days', 0))
                ohp = float(opp.get('hp', 0.0))
                pressure = 0
                if ono >= 1:
                    pressure += 1
                if ohp <= 4:
                    pressure += 1
                if obudget >= b:
                    pressure += 1
                if req <= supply:
                    pressure += 1
                dangerous_prev.append((pressure, b))

    if not alive:
        return min(budget, 18.0)

    highest_prev = max(prev_bids) if prev_bids else 0.0
    strongest_live = 0.0
    if dangerous_prev:
        strongest_live = max([x[1] for x in dangerous_prev if x[0] >= 2] or [highest_prev])

    scarcity = (supply - WATER_REQ) / float(MAX_SUPPLY - WATER_REQ)
    if scarcity < 0:
        scarcity = 0.0
    if scarcity > 1:
        scarcity = 1.0
    tight = supply <= 17
    abundant = supply >= 22

    urgency = 0
    if hp <= 3:
        urgency += 2
    elif hp <= 6:
        urgency += 1
    if no_water >= 1:
        urgency += 2
    if tight:
        urgency += 1
    if day >= 8:
        urgency += 1

    reserve_floor = DAILY_SALARY * max(0, 10 - day) * 0.18
    spendable = max(0.0, budget - reserve_floor)
    if spendable <= 0:
        spendable = budget * 0.5

    if urgency >= 4:
        target = max(62.0, strongest_live + 2.0, highest_prev + 1.0)
    elif urgency >= 2:
        target = max(42.0, strongest_live * 0.92 + 2.0, highest_prev * 0.88 + 1.5)
    else:
        if abundant:
            target = 16.0 + (1.0 - scarcity) * 6.0
        else:
            target = max(24.0, highest_prev * 0.45 + 3.0)

    if highest_prev >= 110 and urgency <= 1:
        target = min(target, 34.0)
    if highest_prev >= 150 and hp > 4 and no_water == 0:
        target = min(target, 22.0)

    if hp <= 2 or no_water >= 2:
        target = max(target, 68.0)

    target = min(target, spendable, budget)
    if target < 0:
        target = 0.0
    return float(round(target, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    alive_opponents = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opponents.append(o)

    # If no opponents, spend enough to avoid death.
    if not alive_opponents:
        target = DAILY_SALARY * 0.45
        return min(my_status['budget'], target)

    # Read yesterday bids from immediate previous_trace only.
    yesterday_bids = []
    for o in alive_opponents:
        prev = o.get('previous_trace', {}) or {}
        bid = prev.get('bid', None)
        if bid is not None:
            try:
                yesterday_bids.append(float(bid))
            except Exception:
                pass

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0

    # Estimate how tight the day is: fewer units -> more scarce -> higher bids needed.
    # supply is between 15 and 25; with WATER_REQ=9, units are ~1 or 2.
    units = int(supply / float(WATER_REQ))  # safe integer index behavior
    # units can be 1 or 2 in this range.
    scarcity = 1 if units <= 1 else 0

    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    # Base aggressiveness: if others were bidding very high yesterday (Eric-like), we must not underbid.
    # Eric's survival suggests that bids near ~DAILY_SALARY*1.3 were effective.
    if highest_prev_bid >= DAILY_SALARY * 1.25:
        # If I am healthy, conserve while still contesting; if low hp, match aggressiveness.
        if hp <= 2.0 or no_water_days >= 2:
            desired = DAILY_SALARY * (1.05 if scarcity else 0.75)
        else:
            desired = DAILY_SALARY * (0.80 if scarcity else 0.60)
    else:
        # If yesterday bids were moderate/low, bid enough to stay in the game.
        if hp <= 2.0 or no_water_days >= 2:
            desired = DAILY_SALARY * (0.85 if scarcity else 0.70)
        else:
            desired = DAILY_SALARY * (0.55 if scarcity else 0.45)

    # Convert desired to a safe bid: never exceed budget; also avoid bidding too low when scarcity is high.
    min_contest = DAILY_SALARY * (0.35 if scarcity == 0 else 0.65)
    bid = max(min_contest, desired)

    # If budget is extremely low, bid remaining budget (to avoid wasting turns if close to death).
    if budget <= DAILY_SALARY * 0.15:
        return max(0.0, min(budget, DAILY_SALARY * 0.25))

    return float(min(budget, bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.3)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0

    bid_amount = 0.0
    if my_status['hp'] <= 2:
        bid_amount = DAILY_SALARY * 0.95
    elif my_status['hp'] <= 4:
        bid_amount = DAILY_SALARY * 0.75
    else:
        bid_amount = DAILY_SALARY * 0.5

    if highest_prev_bid > DAILY_SALARY * 0.6:
        bid_amount = max(bid_amount, highest_prev_bid + 5.0)
    elif highest_prev_bid > 0:
        bid_amount = max(bid_amount, highest_prev_bid * 1.05)

    num_water_units = int(day_context['supply'] // WATER_REQ)
    total_active_agents = len(alive_opponents) + 1

    if num_water_units < total_active_agents:
        bid_amount *= 1.15
    elif num_water_units >= total_active_agents * 1.5:
        bid_amount *= 0.85

    final_bid = max(1.0, min(my_status['budget'], bid_amount))

    return final_bid

